# Generated by StageFlip's release (make brew) from Apps/StageFlip/packaging/homebrew/stageflip.rb.template
# in WuNeo-Inc/app-mac-tools. Do not edit here: the next release overwrites it.
cask "stageflip" do
  version "0.6.6-beta.5"
  sha256 "43a7d833e75c698ca64cc55921d95e62d03823a3614bd02e9592820fd8274480"

  # No `verified:` although the download host is not the homepage's: Homebrew
  # verifies that by itself, and warns about the parameter.
  url "https://app-update-feed.wuneo.com/stageflip/StageFlip-#{version}.dmg"
  name "StageFlip"
  desc "Clear the screen for screen sharing, and check the microphone is muted"
  homepage "https://stageflip.wuneo.com/"

  # The update feed the app reads, by the channels the cask follows: stable
  # releases and the Public Beta. Once the first stable release is out, keep
  # only the stable ones (channel nil).
  livecheck do
    url "https://app-update-feed.wuneo.com/stageflip/appcast.xml"
    strategy :sparkle do |items|
      items.select { |item| [nil, "beta"].include?(item.channel) }.map(&:short_version)
    end
  end

  # The app updates itself (Sparkle); Homebrew leaves it alone once installed.
  auto_updates true
  # Sonoma or later (MACOSX_DEPLOYMENT_TARGET = 14.0).
  depends_on macos: :sonoma

  app "StageFlip.app"

  # It lives in the menu bar and is usually running; an uninstall asks it to
  # quit first, which also puts back whatever a stage had put away.
  uninstall quit: "com.wuneo.stageflip"

  # Preferences, caches and the app's own folders. Not the trial's record in
  # ~/Library/Application Support/WuNEO/Shared (sf-layout*.dat) or the keychain
  # (WNStageState*): that is kept apart from the app's folders on purpose, so an
  # uninstall does not start the trial again, and the folder is shared by every
  # WuNEO app. See TrialKeeper in Packages/NeoLicenseKit.
  zap trash: [
    "~/Library/Application Support/com.wuneo.stageflip",
    "~/Library/Application Support/StageFlip",
    "~/Library/Caches/com.wuneo.stageflip",
    "~/Library/HTTPStorages/com.wuneo.stageflip",
    "~/Library/Preferences/com.wuneo.stageflip.plist",
  ]
end
